const FILES = {
 "driver.mjs": "// SCRUM-939 staging proof driver (the till menu search in the BEO lists the best match first): one headless Chromium\n// kept open, steps run on request (GET http://127.0.0.1:47939/<step>.mjs?arg). Credentials by NAME only through\n// scripts/agent/env.mjs need(); never prints a phone, a password, a token, a setting's value or a person's name.\nimport assert from 'node:assert/strict';\nimport { createServer } from 'node:http';\nimport { createRequire } from 'node:module';\nimport { randomUUID } from 'node:crypto';\nimport { mkdirSync, writeFileSync, existsSync, readFileSync } from 'node:fs';\nimport { pathToFileURL } from 'node:url';\nimport { need } from 'file:///C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/scripts/agent/env.mjs';\n\nconst REPO = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p939/';\nconst STEPS = HERE + 'steps/';\nconst REL = 'docs/qa/proof-2026-11-12/SCRUM-939';\nconst OUT = REPO + '/' + REL;\nmkdirSync(OUT, { recursive: true });\nmkdirSync(HERE + 'raw', { recursive: true });\nconst { chromium, request } = createRequire(REPO + '/apps/pos/package.json')('@playwright/test');\n\n// Round 1: 5517eb0da (the ranked search); round 2 (ROUND=2): 84f5bd5ce (one ranked list across categories).\nconst ROUND = process.env.ROUND === '2' ? 2 : 1;\nconst SHA = ROUND === 2 ? '84f5bd5ceea50b88dbb2d980ae4b1ba845267efc' : '5517eb0da6a7931f9b39e626b2edef92b9ce8cab';\nconst POS = 'https://oto-pos-web-staging.onrender.com';\nconst LAUNCHER = 'https://oto-launcher-staging.onrender.com';\nconst APP = 'https://oto-app-staging.onrender.com';\n\nconst workFile = HERE + (ROUND === 2 ? 'work2.json' : 'work.json');\nconst st = existsSync(workFile)\n  ? JSON.parse(readFileSync(workFile, 'utf8'))\n  : { unit: 'SCRUM-939 staging proof', round: ROUND, liveCommit: SHA, startedAt: new Date().toISOString(), images: [], log: [], points: {}, pageErrors: [] };\nconst save = () => writeFileSync(workFile, JSON.stringify(st, null, 2) + '\\n');\nsave();\n\n// Names to mask, held in memory only (never written, never printed).\nconst NAMES = new Set();\nconst addNames = (...vals) => {\n  for (const v of vals) {\n    if (typeof v !== 'string') continue;\n    const t = v.trim();\n    if (t.length < 2 || /^ZZ TEST/i.test(t)) continue;\n    NAMES.add(t);\n  }\n};\n\nconst browser = await chromium.launch({ headless: true });\nst.browser = 'Chromium ' + browser.version(); save();\nconst newContext = (viewport = { width: 1440, height: 1000 }) =>\n  browser.newContext({ viewport, timezoneId: 'Asia/Bangkok', locale: 'en-GB', colorScheme: 'light' });\n\n/** One request through a context's cookie jar (browser context or API context); status and body. */\nconst call = async (ctx, origin, method, path, body) => {\n  const headers = method === 'GET' ? {} : { 'Idempotency-Key': randomUUID() };\n  const r = await (ctx.request ?? ctx).fetch(origin + '/api' + path, { method, data: body, headers, timeout: 120000 });\n  const text = await r.text();\n  let b = null;\n  try { b = JSON.parse(text); } catch { b = text.slice(0, 300); }\n  return { status: r.status(), body: b };\n};\n\nconst launcherSignIn = async (ctx, phoneKey = 'STAGING_ADMIN_PHONE', passKey = 'STAGING_ADMIN_PASSWORD') => {\n  const s = await call(ctx, LAUNCHER, 'POST', '/auth/sign-in', { phone: need(phoneKey), password: need(passKey) });\n  return s.status;\n};\nconst handTo = async (ctx, app) => {\n  const h = await call(ctx, LAUNCHER, 'POST', '/auth/handoff', { app });\n  if (h.status !== 200) return { status: h.status, code: h.body?.error?.code ?? null, message: h.body?.error?.message ?? null };\n  const page = await ctx.newPage();\n  const want = '/api/auth/handoff';\n  const exchange = page.waitForResponse((r) => new URL(r.url()).pathname === want && r.request().method() === 'POST', { timeout: 90000 });\n  await page.goto(h.body.launchUrl);\n  const response = await exchange;\n  const status = response.status();\n  await response.finished().catch(() => {});\n  await page.waitForURL((u) => !u.hash.includes('handoff'), { timeout: 60000 }).catch(() => {});\n  return { status: 200, exchange: status, page };\n};\n\n/** Redact the names: text nodes, input values, placeholders and titles. Returns how many runs were masked. */\nconst redact = async (page) =>\n  page.evaluate((strings) => {\n    const needles = [...new Set(strings)].sort((a, b) => b.length - a.length);\n    if (!needles.length) return 0;\n    const esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    const re = new RegExp(needles.map((s) => '(?<![A-Za-z])' + esc(s) + '(?![A-Za-z])').join('|'), 'gi');\n    let n = 0;\n    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n    const hits = [];\n    while (walker.nextNode()) {\n      const t = walker.currentNode;\n      if (t.parentElement?.closest('[data-redacted]')) continue;\n      re.lastIndex = 0;\n      if (re.test(t.nodeValue || '')) hits.push(t);\n    }\n    for (const t of hits) {\n      let html = (t.nodeValue || '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));\n      re.lastIndex = 0;\n      html = html.replace(re, (m) => { n += 1; return `<span data-redacted=\"1\" style=\"background:#3f3f46;color:#3f3f46;border-radius:3px\">${m.replace(/./g, '█')}</span>`; });\n      const span = document.createElement('span');\n      span.setAttribute('data-redacted', 'wrap');\n      span.innerHTML = html;\n      t.parentNode.replaceChild(span, t);\n    }\n    for (const el of document.querySelectorAll('input, textarea')) {\n      re.lastIndex = 0;\n      if (re.test(el.value || '')) { el.style.color = '#3f3f46'; el.style.background = '#3f3f46'; n += 1; }\n      re.lastIndex = 0;\n      if (el.placeholder && re.test(el.placeholder)) { re.lastIndex = 0; el.placeholder = el.placeholder.replace(re, (m) => '█'.repeat(m.length)); n += 1; }\n    }\n    for (const el of document.querySelectorAll('[title]')) {\n      re.lastIndex = 0;\n      if (re.test(el.getAttribute('title') || '')) { re.lastIndex = 0; el.setAttribute('title', el.getAttribute('title').replace(re, '█')); }\n    }\n    return n;\n  }, [...NAMES]);\n\n/** After a redaction: how many names are still readable in the visible text or in a field. */\nconst leaks = async (page) =>\n  page.evaluate((strings) => {\n    const vis = (el) => { const s = getComputedStyle(el); return s.visibility !== 'hidden' && s.display !== 'none'; };\n    const parts = [];\n    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n    while (walker.nextNode()) {\n      const el = walker.currentNode.parentElement;\n      if (!el || el.closest('[data-redacted]') || el.closest('[data-board-hidden]') || !vis(el)) continue;\n      parts.push(walker.currentNode.nodeValue || '');\n    }\n    const text = ' ' + parts.join(' ') + ' ';\n    const fields = [...document.querySelectorAll('input, textarea')].filter((e) => !e.closest('[data-board-hidden]')).map((e) => ((e.style.color === 'rgb(63, 63, 70)' ? '' : e.value) + ' ' + (e.placeholder || ''))).join(' ');\n    const esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    return strings.filter((s) => { const re = new RegExp('(?<![A-Za-z])' + esc(s) + '(?![A-Za-z])', 'i'); return re.test(text) || re.test(fields); }).length;\n  }, [...NAMES]);\n\n/** A picture: names redacted, the leak check passed, optional masks, clip or element. */\nconst shot = async (page, name, opts = {}) => {\n  await page.waitForTimeout(opts.settle ?? 700);\n  const masked = await redact(page);\n  const left = await leaks(page);\n  if (left !== 0) throw new Error('a name is still readable; picture not taken: ' + name);\n  const file = OUT + '/' + name;\n  const o = { path: file, mask: opts.mask ?? [], maskColor: '#3f3f46', fullPage: !!opts.fullPage, ...(opts.clip ? { clip: opts.clip } : {}) };\n  if (opts.element) await opts.element.screenshot({ path: file, mask: o.mask, maskColor: o.maskColor });\n  else await page.screenshot(o);\n  st.images = st.images.filter((i) => i.file !== name);\n  st.images.push({ file: name, at: new Date().toISOString(), shows: opts.shows ?? null, namesMasked: masked, masks: (opts.mask ?? []).length });\n  save();\n  return name;\n};\n\nconst one = (s) => String(s ?? '').replace(/\\s+/g, ' ').trim();\n/** Names out of a string, for anything kept. */\nconst scrub = (s) => {\n  if (typeof s !== 'string') return s;\n  let t = s;\n  for (const n of [...NAMES].sort((a, b) => b.length - a.length)) t = t.replace(new RegExp('(?<![A-Za-z])' + n.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&') + '(?![A-Za-z])', 'gi'), '█');\n  return t.replace(/\\+?\\d[\\d\\s().-]{6,}\\d/g, (m) => ((m.match(/\\d/g) || []).length >= 9 ? '[number]' : m));\n};\n\n/** Page errors, failed api calls (status >= 400) and console errors of a page, kept scrubbed. */\nconst watch = (page, label) => {\n  page.on('pageerror', (e) => { st.pageErrors.push({ page: label, at: new Date().toISOString(), kind: 'pageerror', text: scrub(String(e.message).split('\\n')[0].slice(0, 240)) }); save(); });\n  page.on('console', (m) => { if (m.type() === 'error') { st.pageErrors.push({ page: label, at: new Date().toISOString(), kind: 'console.error', text: scrub(m.text().split('\\n')[0].slice(0, 240)) }); save(); } });\n  page.on('response', (r) => { try { const u = new URL(r.url()); if (r.status() >= 400 && /\\/api\\//.test(u.pathname)) { st.pageErrors.push({ page: label, at: new Date().toISOString(), kind: 'http', text: `${r.request().method()} ${u.pathname.replace(/[0-9a-f]{8}-[0-9a-f-]{27}/g, ':id')} ${r.status()}` }); save(); } } catch {} });\n};\n\nconst ctxs = {};\nconst S = { ROUND, need, st, save, browser, ctxs, newContext, request, call, launcherSignIn, handTo, redact, leaks, shot, addNames, NAMES, SHA, POS, LAUNCHER, APP, OUT, REL, HERE, randomUUID, assert, one, scrub, watch };\n\nconst server = createServer(async (req, res) => {\n  const u = new URL(req.url ?? '/', 'http://x');\n  const file = decodeURIComponent(u.pathname.slice(1));\n  const arg = u.search ? decodeURIComponent(u.search.slice(1)) : '';\n  let out;\n  try {\n    if (file === 'STOP') {\n      const mod = await import(pathToFileURL(STEPS + 'signout.mjs').href + '?t=' + Date.now());\n      out = await mod.default(S, arg).catch((e) => ({ error: String(e?.message ?? e).slice(0, 500) }));\n      save();\n      res.setHeader('content-type', 'application/json');\n      res.end(JSON.stringify(out, null, 2));\n      await browser.close();\n      server.close();\n      process.exit(0);\n    }\n    const mod = await import(pathToFileURL(STEPS + file).href + '?t=' + Date.now());\n    out = { ok: true, result: await mod.default(S, arg) };\n  } catch (e) {\n    out = { ok: false, error: scrub(String(e?.stack ?? e)).slice(0, 3000) };\n  }\n  st.log.push({ at: new Date().toISOString(), step: file, arg, ok: out.ok });\n  save();\n  res.setHeader('content-type', 'application/json');\n  res.end(JSON.stringify(out, null, 2));\n});\nserver.listen(47939, '127.0.0.1', () => console.log('driver ready on 47939'));\n",
 "go.mjs": "// Call one driver step with an encoded argument: node go.mjs <step> <arg>\nconst [step, arg = ''] = process.argv.slice(2);\nconst r = await fetch('http://127.0.0.1:47939/' + step + '.mjs' + (arg ? '?' + encodeURIComponent(arg) : ''), { signal: AbortSignal.timeout(290000) });\nconst j = await r.json();\nconsole.log(JSON.stringify(j, null, 1).slice(0, 9000));\n",
 "deploys.mjs": "// READ-ONLY. The named oto-app-staging deploy of SCRUM-939 by id, what it serves now, and the api's live deploy (the\n// till menu door's source). Never prints the key. node deploys.mjs <out.json> [tag]\nimport { writeFileSync, existsSync, readFileSync } from 'node:fs';\nimport { need } from 'file:///C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/scripts/agent/env.mjs';\nconst headers = { authorization: `Bearer ${need('RENDER_API_KEY')}`, accept: 'application/json' };\nconst get = async (path) => { const r = await fetch('https://api.render.com/v1' + path, { headers, signal: AbortSignal.timeout(60000) }); return r.ok ? r.json() : { _status: r.status }; };\n// The named app deploy: round 1 dep-dbqpvdgn74is73ctte50 (5517eb0da); round 2 (4th argument) dep-dbqq9jd6e07s73fviihg (84f5bd5ce).\nconst want = { 'oto-app-staging': process.argv[4] ?? 'dep-dbqpvdgn74is73ctte50', 'oto-api-staging': null };\nconst services = (await get('/services?limit=50')).map((r) => r.service ?? r).filter((s) => /-staging$/.test(s.name));\nconst out = process.argv[2];\nconst tag = process.argv[3] ?? 'read';\nconst state = existsSync(out) ? JSON.parse(readFileSync(out, 'utf8')) : {};\nconst snap = { readAt: new Date().toISOString(), services: {} };\nfor (const [name, dep] of Object.entries(want)) {\n  const s = services.find((x) => x.name === name);\n  if (!s) { snap.services[name] = null; continue; }\n  const d = dep ? await get(`/services/${s.id}/deploys/${dep}`) : null;\n  const list = (await get(`/services/${s.id}/deploys?limit=5`)).map((x) => x.deploy ?? x);\n  const live = list.find((x) => x.status === 'live');\n  snap.services[name] = {\n    named: d ? { id: d.id, status: d.status, sha: d.commit?.id, createdAt: d.createdAt, finishedAt: d.finishedAt, trigger: d.trigger ?? null } : null,\n    live: live ? { id: live.id, sha: live.commit?.id, createdAt: live.createdAt, finishedAt: live.finishedAt } : null,\n    latest: list[0] ? { id: list[0].id, status: list[0].status, sha: list[0].commit?.id } : null,\n  };\n}\nstate[tag] = snap;\nwriteFileSync(out, JSON.stringify(state, null, 2) + '\\n');\nconsole.log(JSON.stringify(snap, null, 1));\n",
 "receipt.mjs": "// Builds docs/qa/proof-2026-11-12/SCRUM-939/receipt.json from the driver's work file: the lists each search showed,\n// in the order shown, routes, statuses and ids, scrubbed (no staff name, no phone, no cookie, no key). node receipt.mjs\nimport { readFileSync, writeFileSync, readdirSync } from 'node:fs';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p939/';\nconst DIR = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/docs/qa/proof-2026-11-12/SCRUM-939/';\nconst st = JSON.parse(readFileSync(HERE + 'work.json', 'utf8'));\nconst pics = readdirSync(DIR).filter((f) => f.endsWith('.png')).sort();\n// \"French friesCF-11฿175\" -> \"French fries | CF-11 | ฿175\"\nconst item = (t) => t.replace(/Party only/, ' [Party only] ').replace(/(CF-[\\d-]+|RC-[\\d-]+|PARTY-[0-9A-F]+)(฿[\\d,]+)$/, ' | $1 | $2').replace(/\\s+/g, ' ').trim();\nconst search = (s) => ({ typed: s.typed, count: s.count, listed: s.listed.map(item), headings: s.groups.map((g) => `${g.heading} (${g.items})`), notFromTheTillOffered: s.clearShown, empty: s.empty ?? null, picture: s.picture ?? null });\nconst run = (r) => r && { at: r.at, button: r.tid, nothingTyped: { count: r.unfiltered.count, headingsInOrder: r.unfiltered.groups.map((g) => `${g.heading} (${g.items})`), firstItems: r.unfiltered.first.map(item), notFromTheTillOffered: r.unfiltered.clear, picture: r.unfiltered.picture ?? null }, searches: r.searches.map(search), picked: r.pickedText ? item(r.pickedText) : null, closedAfterPick: r.closedAfterPick ?? null };\nconst S = st.searches;\nconst find = (key, word) => S[key].flatMap((r) => r.searches).find((s) => s.typed === word);\nconst line = (l) => `${l.itemName} | code ${l.productCode ?? '-'} | qty ${l.quantity} | price ${l.price} | included ${l.included}`;\nconst images = pics.map((f) => {\n  const i = st.images.find((x) => x.file === f);\n  return i ? { file: f, at: i.at, shows: i.shows, namesMasked: i.namesMasked, masks: i.masks } : { file: f };\n});\nconst pass = (b) => (b ? 'PASS' : 'FAIL');\nconst fries = find('kids0', 'fries');\nconst pep = find('kids0', 'pepperoni');\nconst pizza = find('kids1-juice-retake', 'pizza');\nconst juice = find('kids1-juice-retake', 'juice');\nconst cf24 = find('kids0', 'CF-24');\nconst remove = find('kids0-coded', 'remove');\nconst barJuice = find('bar0', 'juice');\nconst saved = st.saves.first.read;\nconst receipt = {\n  unit: 'SCRUM-939 staging proof',\n  ticket: 'SCRUM-939',\n  title: 'The till menu search in the BEO lists the best match first and never matches scattered letters',\n  landed: '5517eb0da6a7931f9b39e626b2edef92b9ce8cab (one commit: apps/oto-app/shared/tillMenu.ts tillMenuSearchScore, client/src/components/beo/till-menu-picker.tsx, tests/till-menu-search.check.ts)',\n  deploys: {\n    file: 'deploys.json (before 11:19Z and after 11:25Z)',\n    app: 'oto-app-staging dep-dbqpvdgn74is73ctte50 live 11:18:04Z at 5517eb0da, still live at the end: the whole run was on it.',\n    api: 'oto-api-staging (the menu the door reads) went live at 6080dc815 (dep-dbqpvk0n74is73ctttig, 11:20:10Z) before the run started (11:20:33Z); 6080dc815 contains 5517eb0da. The search is client-side in the app; the api only supplies the menu.',\n  },\n  startedAt: st.startedAt,\n  finishedAt: st.signOut?.at ?? null,\n  browser: 'Headless ' + st.browser + ' (Playwright), one browser for the whole run, closed at the end',\n  rules: 'One ZZ TEST party only, deleted and read back gone on the app and the till; no template created, edited or deleted (a new-template dialog opened and closed with Cancel, never saved); no POS product created; nothing printed (party on 25 Nov; the park names no party slips station); no payment; no direct database access; staff names held in memory for masking only; the signed-in initials masked',\n  viewer: { role: st.app.role, park: st.app.centralFlorestaName.trim(), linkedTillBranch: st.posMenu.platformBranch.name, tillMenuDoor: st.app.tillMenuDoor },\n  party: st.event,\n  points: {\n    p1_fries: { result: pass(fries.listed[0]?.startsWith('French fries') && !fries.listed.some((t) => /Porridge|Vegetarian breakfast|Syrniki/.test(t))), typed: 'fries', listed: fries.listed.map(item), picture: fries.picture, before: 'SCRUM-905 picture 12: 34 items, French fries 15th' },\n    p2_searches: {\n      result: pass(pep.listed.length === 1 && /^Pepperoni/.test(pep.listed[0]) && pizza.listed.length === 9 && pizza.groups.every((g) => g.heading === 'Pizza') && !juice.listed.some((t) => /wine/i.test(t)) && cf24.listed.length === 1 && /^Margherita/.test(cf24.listed[0])),\n      pepperoni: search(pep), pizza: search(pizza), juice: search(juice), 'CF-24': search(cf24),\n    },\n    p3_pickAfterSearch: {\n      result: pass(saved.kitchen.kids[0]?.itemName === 'French fries' && saved.kitchen.kids[0]?.productCode === 'CF-11'),\n      picked: S.kids0[0].pickedText ? item(S.kids0[0].pickedText) : null, from: 'the \"fries\" search on the first kids line',\n      save: { putStatus: st.saves.first.putStatus, writes: st.saves.first.writes, toasts: st.saves.first.toasts },\n      readBackAfterSave: { route: saved.route, status: saved.status, kids: saved.kitchen.kids.map(line) },\n      afterReload: 'the line shows French fries and CF-11 (picture 04b)',\n      pictures: ['04a-p3-picked-french-fries-before-save.png', '04b-p3-after-save-and-reload-french-fries-kept.png'],\n    },\n    p4_nothingTyped: {\n      result: pass(S.kids0[0].unfiltered.count === 143 && S['kids0-coded'][0].unfiltered.clear && remove.clearShown),\n      count: S.kids0[0].unfiltered.count, scrum905Count: 143, doorCount: st.app.tillMenuDoor.park.count,\n      codedLine: { nothingTypedCount: S['kids0-coded'][0].unfiltered.count, notFromTheTillOffered: S['kids0-coded'][0].unfiltered.clear, remove: search(remove), clear: search(find('kids0-coded', 'clear')), 'not from': search(find('kids0-coded', 'not from')) },\n      pictures: ['01-p4-kitchen-line-nothing-typed.png', '05-p4-coded-line-search-remove-not-from-the-till.png'],\n    },\n    p5_settingsNewTemplate: {\n      result: pass(st.settings.fries.listed[0]?.startsWith('French fries') && st.settings.unchanged && st.settings.dialogClosed),\n      dialog: st.settings.dialogTitle, nothingTyped: { count: st.settings.unfiltered.count, headings: st.settings.unfiltered.groups.map((g) => `${g.heading} (${g.items})`) },\n      fries: { count: st.settings.fries.count, listed: st.settings.fries.listed.map(item) },\n      closedWith: st.settings.closedWith, dialogClosed: st.settings.dialogClosed,\n      templates: { before: st.settings.before.length, after: st.settings.after.length, unchanged: st.settings.unchanged },\n      picture: st.settings.picture,\n    },\n    p6_barPlan: {\n      result: pass(S.bar0[0].unfiltered.groups[0]?.heading === 'Coffee' && barJuice.listed.length > 0 && barJuice.groups.every((g) => /juice|BEO only/i.test(g.heading))),\n      run: run(S.bar0[0]),\n      pictures: ['06a-p6-bar-line-nothing-typed-bar-first.png', '06b-p6-bar-search-juice.png'],\n    },\n  },\n  searchRuns: { kids0: run(S.kids0[0]), kids0Coded: run(S['kids0-coded'][0]), bar0: run(S.bar0[0]), kids1Retake: run(S['kids1-juice-retake'][0]), kids1Odd: run(S['kids1-odd'][0]) },\n  odd: [\n    'Across headings the menu order holds: \"chicken\" lists Grilled chicken (Sides) and Caesar salad — With chicken (Salads) before Chicken schnitzel (Mains) and puts Chicken soup (Kids) last, though both names start with the word (picture 08). Within a heading the best match is first (Chicken schnitzel above Honey balsamic chicken). cmdk 1.1.1 tries to move the best group up but looks groups up by an internal id against the heading, so groups never move.',\n    '\"water\" lists Fresh watermelon juice first (Juice heading comes before Soft drinks), then the three waters.',\n    '\"fry\" finds nothing (singular of fries); \"margarita\" finds nothing (the menu spells Margherita).',\n    '\"nugget\" finds only \"ZZ TEST 829 nuggets\" (Party only); \"juice\" also lists \"ZZ TEST 829 juice\" (Party only): two earlier test items still on the staging till as BEO-only products.',\n    '\"bar\" lists Barley & quinoa warm salad first, then every bar item (found by station); \"kids\" lists the 8 Kids dishes and the 4 Kids juices (by category).',\n  ],\n  pageErrors: st.pageErrors,\n  cleanup: st.cleanup,\n  signOut: st.signOut,\n  images,\n};\n// Round 2: the follow-up 84f5bd5ce (one ranked list across categories), from work2.json.\nconst st2 = JSON.parse(readFileSync(HERE + 'work2.json', 'utf8'));\n{\n  const S2 = st2.searches;\n  const f2 = (key, word) => S2[key].flatMap((r) => r.searches).find((s) => s.typed === word);\n  const noHeadings = (s) => s.groups.every((g) => g.heading === null);\n  const chicken = f2('kids0', 'chicken');\n  const water = f2('kids0', 'water');\n  const fries2 = f2('kids0', 'fries');\n  const pizza2 = f2('kids0', 'pizza');\n  const juice2 = f2('kids0', 'juice');\n  const cf242 = f2('kids0', 'CF-24');\n  const remove2 = f2('kids0-coded', 'remove');\n  const pizzaCoded = f2('kids0-coded', 'pizza');\n  const friesCoded = f2('kids0-coded', 'fries');\n  const startsChicken = chicken.listed.filter((t) => /^chicken/i.test(t)).length;\n  const waterWords = ['S.Pellegrino sparkling water', 'Acqua Panna mineral water', 'Mineral water'];\n  const at = (s, n) => s.listed.findIndex((t) => t.startsWith(n));\n  receipt.round2 = {\n    landed: '84f5bd5ceea50b88dbb2d980ae4b1ba845267efc (fix(oto-app): one ranked list for a till menu search, across categories; contains 5517eb0da)',\n    deploys: {\n      file: 'deploys.json keys round2-before (11:40Z) and round2-after (11:44Z)',\n      app: 'oto-app-staging dep-dbqq9jd6e07s73fviihg live 11:39:48Z at 84f5bd5ce, still live at the end: the whole round was on it.',\n      api: 'oto-api-staging served 6080dc815 for the till menu read (11:40Z) and every search; it moved to 8e7f7d315 (dep-dbqqaeijnfac739er580) at 11:43:17Z, before the clean-up read-backs (11:43:52Z). The search is client-side in the app.',\n    },\n    startedAt: st2.startedAt,\n    finishedAt: st2.signOut?.at ?? null,\n    party: st2.event,\n    points: {\n      p1_chicken: { result: pass(startsChicken === 2 && chicken.listed.slice(0, startsChicken).every((t) => /^chicken/i.test(t)) && noHeadings(chicken)), expected: 'names starting with \"chicken\" first, no headings', search: search(chicken), headingsShown: !noHeadings(chicken) },\n      p2_water: {\n        result: pass(waterWords.every((w) => at(water, w) >= 0 && at(water, w) < at(water, 'Fresh watermelon juice'))),\n        expected: 'S.Pellegrino sparkling water, Acqua Panna mineral water and Mineral water before Fresh watermelon juice',\n        search: search(water),\n        why: 'tillMenuSearchScore gives 0.9 to \"the start of one of its words\": \"water\" is the start of the word \"watermelon\", so Fresh watermelon juice scores 0.9 like the three waters (whole word \"water\"); equal answers keep the menu order, and Juice (CF-63) comes before Soft drinks (CF-65). No whole-word tier above the word-start tier.',\n      },\n      p3_unchanged: {\n        result: pass(fries2.listed[0]?.startsWith('French fries') && fries2.listed[1]?.startsWith('Sweet potato fries') && fries2.count === 2 && pizza2.count === 9 && cf242.count === 1 && /^Margherita/.test(cf242.listed[0]) && juice2.count === 7),\n        fries: search(fries2), pizza: search(pizza2), juice: search(juice2), 'CF-24': search(cf242),\n        juiceOrderChanged: 'round 1 (by heading): orange, watermelon, Apple, Orange, Pineapple, Cranberry mors, ZZ TEST 829 juice; round 2 (one list): the three names with \"juice\" first (ZZ TEST 829 juice third), then the four Kids juices found by their category',\n      },\n      p4_nothingTypedAndClearedBox: {\n        result: pass(S2.kids0[0].unfiltered.count === 143 && S2.kids0[0].unfiltered.groups.length === 25 && S2.bar0[0].unfiltered.groups[0]?.heading === 'Coffee' && S2['kids0-coded'][0].searchBoxAtOpen === '' && S2['kids0-after-escape'][0].searchBoxAtOpen === ''),\n        kitchen: { count: S2.kids0[0].unfiltered.count, headings: S2.kids0[0].unfiltered.groups.map((g) => `${g.heading} (${g.items})`) },\n        bar: { count: S2.bar0[0].unfiltered.count, headings: S2.bar0[0].unfiltered.groups.map((g) => `${g.heading} (${g.items})`) },\n        searchBoxAfterPick: { picked: S2.kids0[0].pickedText ? item(S2.kids0[0].pickedText) : null, closedAfterPick: S2.kids0[0].closedAfterPick, lastTypedBeforePick: 'fries', boxWhenReopened: S2['kids0-coded'][0].searchBoxAtOpen },\n        searchBoxAfterEscape: { lastTypedBeforeEscape: 'fries', boxWhenReopened: S2['kids0-after-escape'][0].searchBoxAtOpen },\n        pictures: ['r2-01-p4-kitchen-line-nothing-typed-headings.png', 'r2-08-p4-reopened-after-pick-box-empty.png', 'r2-11-p4-bar-line-nothing-typed-bar-first.png'],\n      },\n      p5_codedLine: {\n        result: pass(S2['kids0-coded'][0].unfiltered.clear && remove2.clearShown && !pizzaCoded.clearShown && !friesCoded.clearShown),\n        nothingTyped: { notFromTheTillOffered: S2['kids0-coded'][0].unfiltered.clear },\n        remove: search(remove2), clear: search(f2('kids0-coded', 'clear')), pizza: search(pizzaCoded), fries: search(friesCoded),\n        pictures: ['r2-09-p5-coded-line-search-remove.png', 'r2-10-p5-coded-line-food-word-no-not-from-the-till.png'],\n      },\n      p6_settingsNewTemplate: {\n        result: pass(st2.settings.fries.count === 4 && st2.settings.fries.groups.length === 1 && st2.settings.fries.groups[0].heading === null && st2.settings.unchanged && st2.settings.dialogClosed),\n        dialog: st2.settings.dialogTitle, nothingTyped: { count: st2.settings.unfiltered.count, headings: st2.settings.unfiltered.groups.length },\n        fries: { count: st2.settings.fries.count, listed: st2.settings.fries.listed.map(item), headings: st2.settings.fries.groups.map((g) => g.heading) },\n        closedWith: st2.settings.closedWith, templates: { before: st2.settings.before.length, after: st2.settings.after.length, unchanged: st2.settings.unchanged },\n        picture: st2.settings.picture,\n      },\n    },\n    searchRuns: { kids0: run(S2.kids0[0]), kids0Coded: run(S2['kids0-coded'][0]), kids0AfterEscape: run(S2['kids0-after-escape'][0]), bar0: run(S2.bar0[0]) },\n    odd: [\n      '\"water\": Fresh watermelon juice still first (point 2): the start of a word (\"watermelon\") ranks with a whole word.',\n      '\"juice\" now puts the party-only \"ZZ TEST 829 juice\" third, above the four Kids juices (a name match outranks a category match); that item and \"ZZ TEST 829 nuggets\" are earlier test products still on the staging till.',\n      '\"bar\" still lists Barley & quinoa warm salad first, then the 65 bar items by station; \"remove\" on a line with no code lists \"Not on the till\\'s menu\".',\n    ],\n    pageErrors: st2.pageErrors,\n    cleanup: st2.cleanup,\n    signOut: st2.signOut,\n    images: pics.filter((f) => f.startsWith('r2-')).map((f) => { const i = st2.images.find((x) => x.file === f); return i ? { file: f, at: i.at, shows: i.shows, namesMasked: i.namesMasked, masks: i.masks } : { file: f }; }),\n  };\n  receipt.images = receipt.images.filter((i) => !i.file.startsWith('r2-'));\n}\nlet text = JSON.stringify(receipt, null, 2);\ntext = text.replace(/\\+?\\d[\\d\\s().-]{7,}\\d/g, (m) => ((m.match(/\\d/g) || []).length >= 9 && !/^\\d{4}-\\d{2}/.test(m) ? '[number]' : m));\nwriteFileSync(DIR + 'receipt.json', text + '\\n');\nconsole.log('written', text.length, 'images', images.length);\nconsole.log(JSON.stringify(Object.fromEntries(Object.entries(receipt.points).map(([k, v]) => [k, v.result]))));\nconsole.log('round2', JSON.stringify(Object.fromEntries(Object.entries(receipt.round2.points).map(([k, v]) => [k, v.result]))));\n",
 "namecheck.mjs": "// Counts held staff names in a file (never prints them). node namecheck.mjs <file>\nimport { readFileSync } from 'node:fs';\nconst t = readFileSync(process.argv[2], 'utf8');\nconst names = readFileSync('C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p939/raw/names.txt', 'utf8').split('\\n').filter((n) => n.trim().length >= 3);\nconst esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\nconst hits = names.filter((n) => new RegExp('(?<![A-Za-z])' + esc(n.trim()) + '(?![A-Za-z])', 'i').test(t));\nconsole.log('name hits:', hits.length, 'lengths:', hits.map((h) => h.length).join(','));\nconsole.log('token-like:', /[0-9a-f]{48}/.test(t));\n",
 "bundle.mjs": "// Writes docs/qa/proof-2026-11-12/SCRUM-939/proof.mjs: every script of the run as text, and `node proof.mjs <folder>`\n// writes them back out. node bundle.mjs\nimport { readFileSync, readdirSync, writeFileSync } from 'node:fs';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p939/';\nconst OUT = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/docs/qa/proof-2026-11-12/SCRUM-939/proof.mjs';\nconst files = {};\nfor (const f of ['driver.mjs', 'go.mjs', 'deploys.mjs', 'receipt.mjs', 'namecheck.mjs', 'bundle.mjs']) files[f] = readFileSync(HERE + f, 'utf8');\nfor (const f of readdirSync(HERE + 'steps').filter((x) => x.endsWith('.mjs')).sort()) files['steps/' + f] = readFileSync(HERE + 'steps/' + f, 'utf8');\nconst head = `// SCRUM-939 staging proof harness (the till menu search in the BEO lists the best match first), as run on 12 November\n// 2026 against oto-app-staging dep-dbqpvdgn74is73ctte50 at 5517eb0da (oto-api-staging live at 6080dc815, which contains\n// it, from 11:20:10Z, before the run). Built from the SCRUM-905 harness (its sign-in, masking, ZZ TEST party and\n// clean-up); searches.mjs, settings939.mjs and names.mjs are new. One file: every script of the run as text;\n// \\`node proof.mjs <folder>\\` writes them out. The driver keeps one headless Chromium open and runs a step per request\n// (node go.mjs <step> \"<arg>\"); credentials by NAME only through scripts/agent/env.mjs need(); staff names held in\n// memory for masking only. The run, in order (UTC):\n//   deploys.mjs deploys.json before (11:19) | app-in (11:20) | names | pos-menu | create-event (11:20:59) |\n//   act reload | act open|accordion-kitchen-plan | act click|button-add-first-menu-kids |\n//   searches kids-0: nothing typed (01), pepperoni (03a), pizza, juice, CF-24 (03d), french, fry, chips, margarita, coke,\n//     water, nugget, chicken, kids, bar, kitchen, fries (02); pick CF-11 | pic 04a | save first (11:22:46) | act reload |\n//   act open kitchen | pic 04b | searches kids-0 (coded): remove (05), clear, not from | act open|accordion-bar-plan |\n//   act click|button-add-bar-extra | searches bar-0: nothing typed (06a), juice (06b), fries, water | settings939 (07) |\n//   act reload | act open kitchen | act click|button-add-menu-extra-kids | searches kids-1: pizza (03b), juice (03c),\n//   Margherita, fries (03b and 03c retaken there: the list kept its scroll from the earlier search, now scrolled to its\n//   top) | searches kids-1: chicken (08), soup, schnitzel, french fries, fries french, sweet potato | cleanup (11:24:50) |\n//   GET /STOP (signs every session out, closes the browser) | deploys.mjs deploys.json after | receipt.mjs |\n//   namecheck.mjs receipt.json. look.mjs is an operator aid (unused in this run).\n// Round 2 (ROUND=2 node driver.mjs; work2.json), against oto-app-staging dep-dbqq9jd6e07s73fviihg at 84f5bd5ce (one\n// ranked list across categories), in order (UTC): deploys.mjs deploys.json round2-before dep-dbqq9jd6e07s73fviihg\n//   (11:40) | app-in | names | pos-menu | create-event \"ZZ TEST 939 r2 till menu search\" (11:40:45) | act reload |\n//   act open kitchen | act click|button-add-first-menu-kids | searches kids-0: nothing typed (r2-01), chicken (r2-02),\n//   water (r2-03), pizza (r2-05), juice (r2-06), CF-24 (r2-07), pepperoni, soup, kids, bar, remove, fries (r2-04);\n//   pick CF-11 | searches kids-0 (coded, reopened after the pick: box read): nothing typed (r2-08), remove (r2-09),\n//   pizza (r2-10), clear, fries; Escape | searches kids-0 (reopened after Escape: box read) | act open bar |\n//   act click|button-add-bar-extra | searches bar-0: nothing typed (r2-11), juice (r2-12), water, chicken |\n//   settings939 r2-13-... | cleanup (11:43:52) | GET /STOP | deploys.mjs ... round2-after | receipt.mjs | namecheck.mjs.\nimport { mkdirSync, writeFileSync } from 'node:fs';\nimport { dirname, resolve } from 'node:path';\n`;\nconst body = `const FILES = ${JSON.stringify(files, null, 1)};\nconst dir = process.argv[2];\nif (!dir) { console.log(Object.keys(FILES).join('\\\\n')); process.exit(0); }\nfor (const [name, text] of Object.entries(FILES)) { const f = resolve(dir, name); mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, text); }\nconsole.log('written', Object.keys(FILES).length, 'files to', dir);\n`;\nwriteFileSync(OUT, head + body);\nconsole.log('proof.mjs', Object.keys(files).length, 'files');\n",
 "steps/act.mjs": "// Small UI actions on the BEO sheet, one per call. arg = \"<action>|<a>|<b>\"\n//   click|<testId>            click an element by test id\n//   type|<testId>|<words>     click an EditableText by test id, type, leave the field (Tab)\n//   tab|kids|adults           the kitchen plan's menu tab\n//   open|<accordion tid>      open a section\n//   reload                    reload the BEO (the board with ?beo=)\n//   row|<testId>              the row's text and the title of its code chip\nimport { openBeo, openSection } from './applib.mjs';\nexport default async (S, arg) => {\n  const [action, a = '', b = ''] = arg.split('|');\n  const page = S.ctxs.app.page;\n  if (action === 'reload') { await openBeo(S, { reload: true }); return { reloaded: true }; }\n  if (action === 'open') { await openSection(page, a); return { opened: a }; }\n  if (action === 'tab') { await page.getByTestId(`button-menu-tab-${a}`).click(); await page.waitForTimeout(400); return { tab: a }; }\n  if (action === 'click') { const l = page.getByTestId(a).first(); await l.scrollIntoViewIfNeeded(); await l.click(); await page.waitForTimeout(500); return { clicked: a }; }\n  if (action === 'type') {\n    const l = page.getByTestId(a).first();\n    await l.scrollIntoViewIfNeeded();\n    await l.click();\n    await page.waitForTimeout(200);\n    const input = page.locator(`[data-testid=\"${a}\"] input, input[data-testid=\"${a}\"]`).first();\n    const focused = (await input.count()) ? input : page.locator(':focus');\n    await focused.fill(b);\n    await page.keyboard.press('Tab');\n    await page.waitForTimeout(400);\n    return { typed: b, into: a };\n  }\n  if (action === 'row') {\n    const l = page.getByTestId(a).first();\n    await l.scrollIntoViewIfNeeded().catch(() => {});\n    const text = S.scrub(S.one(await l.innerText().catch(() => '')));\n    const chip = l.locator('span.font-mono').first();\n    return { text, codeTitle: (await chip.count()) ? await chip.getAttribute('title') : null, searchButton: await l.locator('[data-testid^=\"button-till-menu-\"]').count() };\n  }\n  throw new Error('unknown action ' + action);\n};\n",
 "steps/app-in.mjs": "// The staging administrator in the OTO App through the launcher; names of the signed-in person and of the park's\n// people held for masking only; Central Floresta found by name; the set menu templates and birthday packages read\n// (never changed); the app's till-menu door read for the park and for every park.\nexport default async (S) => {\n  if (!S.ctxs.app) {\n    const ctx = await S.newContext({ width: 1440, height: 1000 });\n    ctx.setDefaultTimeout(30000);\n    const si = await S.launcherSignIn(ctx);\n    S.assert.equal(si, 200, 'launcher sign-in ' + si);\n    const h = await S.handTo(ctx, 'oto_app');\n    S.assert.equal(h.status, 200, 'handoff ' + JSON.stringify(h));\n    S.watch(h.page, 'app-admin');\n    S.ctxs.app = { ctx, page: h.page };\n  }\n  const { ctx } = S.ctxs.app;\n  const u = await S.call(ctx, S.APP, 'GET', '/user');\n  S.assert.equal(u.status, 200, '/api/user ' + u.status);\n  for (const v of [u.body?.fullName, u.body?.firstName, u.body?.lastName, u.body?.nickname, u.body?.displayName, u.body?.username, u.body?.name]) {\n    S.addNames(v);\n    if (typeof v === 'string') for (const part of v.trim().split(/\\s+/)) if (part.length >= 3) S.addNames(part);\n  }\n  const br = await S.call(ctx, S.APP, 'GET', '/branches');\n  const list = Array.isArray(br.body) ? br.body : [];\n  const cf = list.find((b) => /Central Floresta/.test(b.name));\n  S.assert.ok(cf, 'Central Floresta not found');\n  const em = await S.call(ctx, S.APP, 'GET', `/employees?branchId=${cf.id}`);\n  const people = Array.isArray(em.body) ? em.body : em.body?.employees ?? [];\n  for (const e of people) {\n    S.addNames(e.nickname, e.fullName, e.thaiName);\n    if (typeof e.fullName === 'string') for (const part of e.fullName.trim().split(/\\s+/)) if (part.length >= 3) S.addNames(part);\n  }\n  const sm = await S.call(ctx, S.APP, 'GET', '/beo/set-menu-templates');\n  const menus = Array.isArray(sm.body) ? sm.body : sm.body?.templates ?? [];\n  const pk = await S.call(ctx, S.APP, 'GET', '/beo/birthday-packages');\n  const pkgs = (Array.isArray(pk.body) ? pk.body : pk.body?.packages ?? []);\n  const one = await S.call(ctx, S.APP, 'GET', `/beo/till-menu?parkId=${cf.id}`);\n  const all = await S.call(ctx, S.APP, 'GET', '/beo/till-menu');\n  const park = one.body?.parks?.[0] ?? null;\n  S.st.app = {\n    role: u.body?.role ?? null,\n    centralFloresta: cf.id, centralFlorestaName: cf.name.trim(), coreBranchId: cf.coreBranchId ?? null,\n    parks: list.map((b) => ({ id: b.id, name: b.name, linked: !!b.coreBranchId, archived: !!b.archived })),\n    peopleAtPark: people.length,\n    setMenuTemplates: menus.map((m) => ({ id: m.id, name: m.name, isActive: m.isActive, branchId: m.branchId ?? null, items: (m.items ?? []).map((i) => ({ id: i.id, type: i.type, label: i.label, productCode: i.productCode ?? null, options: i.options ?? null, optionProductCodes: i.optionProductCodes ?? null })) })),\n    packages: pkgs.map((p) => ({ id: p.id, name: p.name, branchId: p.branchId ?? null, isActive: p.isActive, setMenuTemplateId: p.setMenuTemplateId ?? null })),\n    tillMenuDoor: {\n      park: { route: 'GET /api/beo/till-menu?parkId=<Central Floresta>', status: one.status, parkStatus: park?.status ?? null, message: park?.message ?? null, readAt: park?.readAt ?? null, count: park?.items?.length ?? null },\n      all: { route: 'GET /api/beo/till-menu', status: all.status, parks: (all.body?.parks ?? []).map((p) => ({ parkName: p.parkName, status: p.status, count: p.items.length, message: p.message })) },\n    },\n  };\n  S.st.tillMenuItems = park?.items ?? [];\n  S.save();\n  return { ...S.st.app, setMenuTemplates: S.st.app.setMenuTemplates.length, namesHeld: S.NAMES.size };\n};\n",
 "steps/applib.mjs": "// OTO App helpers. The events board behind the BEO sheet carries customers' party names, so it is hidden for every\n// picture (#root made invisible; the sheet, popovers and dialogs are portaled outside it).\nexport async function hideBoard(page) {\n  return page.evaluate(() => {\n    const root = document.getElementById('root');\n    if (!root) return false;\n    root.setAttribute('data-board-hidden', '1');\n    // Opacity, not only visibility: a descendant styled \"visible\" would show through a hidden parent.\n    root.style.visibility = 'hidden';\n    root.style.opacity = '0';\n    return true;\n  });\n}\nexport async function showBoard(page) {\n  await page.evaluate(() => {\n    const root = document.querySelector('[data-board-hidden]');\n    if (root) { root.style.visibility = ''; root.style.opacity = ''; root.removeAttribute('data-board-hidden'); }\n  });\n}\n/** Open the ZZ TEST party's BEO editor (the events board with ?beo=<id>), waiting for its form. */\nexport async function openBeo(S, { reload = true } = {}) {\n  const page = S.ctxs.app.page;\n  if (reload || !(await page.getByTestId('accordion-event-info').isVisible().catch(() => false))) {\n    await page.goto(S.APP + '/studio/events/kanban?beo=' + S.st.event.id, { waitUntil: 'domcontentloaded', timeout: 120000 });\n    await page.getByTestId('accordion-event-info').waitFor({ timeout: 120000 });\n    await page.waitForTimeout(2500);\n  }\n  return page;\n}\n/** Open an accordion section by its trigger's test id (left open when already open). */\nexport async function openSection(page, tid) {\n  const trig = page.getByTestId(tid).first();\n  await trig.waitFor({ state: 'visible', timeout: 60000 });\n  if ((await trig.getAttribute('data-state')) !== 'open') { await trig.click(); await page.waitForTimeout(800); }\n  return trig;\n}\n/** The accordion item around a trigger. */\nexport function sectionOf(page, tid) {\n  return page.getByTestId(tid).first().locator('xpath=ancestor::*[@data-state][not(self::button)][not(self::h3)][1]');\n}\n/** A picture with the board hidden. */\nexport async function appShot(S, name, opts = {}) {\n  const page = S.ctxs.app.page;\n  await hideBoard(page);\n  await page.waitForTimeout(250);\n  try {\n    return await S.shot(page, name, opts);\n  } finally {\n    await showBoard(page);\n  }\n}\n/** The visible text of a locator, scrubbed, on one line. */\nexport async function textOf(S, loc) {\n  return S.scrub(S.one(await loc.innerText().catch(() => '')));\n}\n",
 "steps/cleanup.mjs": "// Clean-up, each read back: the ZZ TEST party deleted through the app's own route (DELETE /api/admin/events/:id;\n// everything on it goes with it by cascade), then read back on the app (the event, its BEO) and on the till (the party);\n// the set menu templates counted against the start; no ZZ TEST event of this run left at Central Floresta.\nexport default async (S) => {\n  const { ctx } = S.ctxs.app;\n  const ev = S.st.event;\n  if (!/^ZZ TEST/.test(ev.title)) throw new Error('refusing to delete an event not named ZZ TEST');\n  const del = await S.call(ctx, S.APP, 'DELETE', `/admin/events/${ev.id}`);\n  const appEvent = await S.call(ctx, S.APP, 'GET', `/admin/events/${ev.id}`);\n  const appBeo = await S.call(ctx, S.APP, 'GET', `/events/${ev.id}/beo`);\n  const till = await S.call(S.ctxs.pos.api, S.POS, 'GET', `/parties/${ev.id}?branchId=${S.st.posMenu.platformBranch.id}`);\n  const list = await S.call(ctx, S.APP, 'GET', `/admin/events?range=all&includeArchived=true&branchId=${S.st.app.centralFloresta}`);\n  const left = Array.isArray(list.body) ? list.body.filter((e) => e.id === ev.id || /ZZ TEST 939/.test(String(e.title || ''))).map((e) => ({ id: e.id, title: e.title })) : null;\n  const tm = await S.call(ctx, S.APP, 'GET', '/beo/set-menu-templates');\n  const templatesNow = (Array.isArray(tm.body) ? tm.body : []).map((t) => ({ id: t.id, name: t.name, isActive: t.isActive, updatedAt: t.updatedAt ?? null, items: JSON.stringify(t.items) }));\n  S.st.cleanup = {\n    at: new Date().toISOString(),\n    party: { id: ev.id, title: ev.title, delete: { route: 'DELETE /api/admin/events/:id', status: del.status, error: del.status < 300 ? null : del.body } },\n    readBack: {\n      appEvent: { route: 'GET /api/admin/events/:id', status: appEvent.status },\n      appBeo: { route: 'GET /api/events/:id/beo', status: appBeo.status },\n      tillParty: { route: 'GET /api/parties/:id?branchId=<Central Floresta> (till)', status: till.status, code: till.body?.error?.code ?? null },\n      zzTest939AtCentralFloresta: left,\n    },\n    setMenuTemplates: { count: templatesNow.length, unchangedSinceStart: JSON.stringify(templatesNow) === JSON.stringify(S.st.templatesAtStart ?? []) },\n  };\n  S.save();\n  return S.st.cleanup;\n};\n",
 "steps/create-event.mjs": "// A plain ZZ TEST birthday party at Central Floresta on a future weekday, through the app's own route\n// (POST /api/admin/events). Nothing is printed: the party's day is not today and the park names no party slips station.\nexport default async (S) => {\n  const { ctx } = S.ctxs.app;\n  if (S.st.event?.id) return { already: S.st.event };\n  const title = 'ZZ TEST 939 r2 till menu search';\n  const body = { eventType: 'birthday', title, branchId: S.st.app.centralFloresta, eventDate: '2026-11-25', startTime: '14:00', endTime: '16:00', durationMinutes: 120, numChildren: 8, numAdults: 4, childName: 'ZZ Test Child', status: 'upcoming' };\n  const r = await S.call(ctx, S.APP, 'POST', '/admin/events', body);\n  if (r.status !== 201) throw new Error('create ' + r.status + ' ' + JSON.stringify(r.body).slice(0, 300));\n  S.st.event = { id: r.body.id, title: r.body.title, date: r.body.eventDate, startTime: r.body.startTime, route: 'POST /api/admin/events', status: r.status, createdAt: new Date().toISOString() };\n  S.save();\n  return S.st.event;\n};\n",
 "steps/look.mjs": "// A look at the page for the driver's operator: a scratch picture (never in the proof folder) and the sheet's text.\n// arg = \"<name>|<reload?>|<section tid,...>\"\nimport { openBeo, openSection, hideBoard, showBoard } from './applib.mjs';\nexport default async (S, arg) => {\n  const [name = 'look', reload = '', sections = ''] = arg.split('|');\n  const page = reload === 'beo' ? await openBeo(S, { reload: true }) : S.ctxs.app.page;\n  for (const tid of sections.split(',').filter(Boolean)) await openSection(page, tid);\n  await hideBoard(page);\n  await S.redact(page);\n  await page.screenshot({ path: S.HERE + 'raw/' + name + '.png', fullPage: false });\n  await showBoard(page);\n  const dlg = page.locator('[role=dialog]').first();\n  const text = S.scrub(S.one(await (await dlg.count() ? dlg : page.locator('body')).innerText().catch(() => ''))).slice(0, 4000);\n  return { url: page.url().replace(/[?#].*/, ''), text };\n};\n",
 "steps/names.mjs": "// The held names written to the scratch folder (raw/names.txt) for namecheck.mjs; never printed, never in the repo.\n// Also the set menu templates at the start, for the clean-up's \"unchanged\" read.\nimport { writeFileSync } from 'node:fs';\nexport default async (S) => {\n  writeFileSync(S.HERE + 'raw/names.txt', [...S.NAMES].join('\\n') + '\\n');\n  const r = await S.call(S.ctxs.app.ctx, S.APP, 'GET', '/beo/set-menu-templates');\n  S.st.templatesAtStart = (Array.isArray(r.body) ? r.body : []).map((t) => ({ id: t.id, name: t.name, isActive: t.isActive, updatedAt: t.updatedAt ?? null, items: JSON.stringify(t.items) }));\n  S.save();\n  return { held: S.NAMES.size, templates: S.st.templatesAtStart.length };\n};\n",
 "steps/pic.mjs": "// A picture of the BEO sheet with an element scrolled to a place first. arg = \"<file>|<testId to scroll to>|<block>|<shows>\"\nimport { hideBoard, showBoard } from './applib.mjs';\nexport default async (S, arg) => {\n  const [file, tid = '', block = 'center', shows = ''] = arg.split('|');\n  const page = S.ctxs.app.page;\n  if (tid) {\n    const l = page.getByTestId(tid).first();\n    await l.scrollIntoViewIfNeeded();\n    await l.evaluate((el, block) => el.scrollIntoView({ block }), block);\n    await page.waitForTimeout(400);\n  }\n  const sheet = page.locator('[role=dialog]').first();\n  await hideBoard(page);\n  try {\n    return await S.shot(page, file, { element: (await sheet.count()) ? sheet : undefined, shows });\n  } finally {\n    await showBoard(page);\n  }\n};\n",
 "steps/pick.mjs": "// The picker beside a line: open it, read what it lists (unfiltered), search, pick. Pictures of the sheet.\n// arg = \"<testId of the search button>|<search words>|<code to pick or ->|<picture prefix or ->|<record key>\"\nimport { hideBoard, showBoard } from './applib.mjs';\n\n/** What the open picker lists: groups in order with their item counts, and every option's code. */\nexport async function listed(page, tid) {\n  return page.evaluate((tid) => {\n    const box = document.querySelector('[data-radix-popper-content-wrapper]');\n    if (!box) return null;\n    const groups = [...box.querySelectorAll('[cmdk-group]')].filter((g) => !g.hidden && g.getAttribute('aria-hidden') !== 'true' && getComputedStyle(g).display !== 'none');\n    const opts = [...box.querySelectorAll(`[data-testid^=\"${tid}-option-\"]`)].filter((o) => getComputedStyle(o).display !== 'none' && !o.hidden && o.getAttribute('aria-hidden') !== 'true');\n    return {\n      groups: groups.map((g) => ({ heading: g.querySelector('[cmdk-group-heading]')?.textContent ?? null, items: [...g.querySelectorAll(`[data-testid^=\"${tid}-option-\"]`)].filter((o) => getComputedStyle(o).display !== 'none' && !o.hidden).length })).filter((g) => g.items > 0),\n      options: opts.map((o) => ({ code: o.getAttribute('data-testid').slice(`${tid}-option-`.length), text: (o.textContent ?? '').trim() })),\n      empty: box.querySelector('[cmdk-empty]')?.textContent ?? null,\n      note: box.querySelector(`[data-testid=\"${tid}-unavailable\"]`)?.textContent ?? null,\n      clear: !!box.querySelector(`[data-testid=\"${tid}-clear\"]`),\n    };\n  }, tid);\n}\n\nexport default async (S, arg) => {\n  const [tid, words = '', code = '-', pic = '-', key = tid] = arg.split('|');\n  const page = S.ctxs.app.page;\n  const sheet = page.locator('[role=dialog]').first();\n  const btn = page.getByTestId(tid);\n  await btn.scrollIntoViewIfNeeded();\n  await btn.evaluate((el) => el.scrollIntoView({ block: 'center' }));\n  await page.waitForTimeout(300);\n  const t0 = Date.now();\n  await btn.click();\n  await page.locator('[data-radix-popper-content-wrapper]').waitFor({ timeout: 30000 });\n  // The till's menu loads when the section opens; wait for the list (or the reason there is none).\n  await page.waitForFunction((tid) => !!document.querySelector(`[data-testid=\"${tid}-search\"]`) || /could not|not linked|cannot|not available/.test(document.querySelector(`[data-testid=\"${tid}-unavailable\"]`)?.textContent ?? ''), tid, { timeout: 60000 }).catch(() => {});\n  const openMs = Date.now() - t0;\n  const rec = { at: new Date().toISOString(), tid, openMs, title: await btn.getAttribute('title') };\n  rec.unfiltered = await listed(page, tid);\n  rec.unfilteredCount = rec.unfiltered?.options.length ?? null;\n  rec.firstGroups = rec.unfiltered?.groups.slice(0, 4) ?? null;\n  if (pic !== '-') {\n    await hideBoard(page);\n    rec.pictureList = await S.shot(page, `${pic}a-list.png`, { element: sheet, shows: `${tid}: the picker open, the till's menu unfiltered` });\n    await showBoard(page);\n  }\n  if (words) {\n    await page.getByTestId(`${tid}-search`).fill(words);\n    await page.waitForTimeout(600);\n    rec.search = words;\n    rec.filtered = await listed(page, tid);\n    if (pic !== '-') {\n      await hideBoard(page);\n      rec.pictureSearch = await S.shot(page, `${pic}b-search.png`, { element: sheet, shows: `${tid}: \"${words}\" typed in the picker` });\n      await showBoard(page);\n    }\n  }\n  if (code !== '-') {\n    const opt = page.getByTestId(`${tid}-option-${code}`);\n    rec.pickedText = (await opt.innerText()).replace(/\\s+/g, ' ').trim();\n    await opt.click();\n    await page.waitForTimeout(500);\n    rec.closedAfterPick = !(await page.locator('[data-radix-popper-content-wrapper]').isVisible().catch(() => false));\n    rec.picked = code;\n  } else {\n    await page.keyboard.press('Escape');\n    await page.waitForTimeout(300);\n  }\n  ((S.st.picks ??= {})[key] ??= []).push(rec);\n  S.save();\n  return { ...rec, unfiltered: rec.unfiltered ? { groups: rec.unfiltered.groups, count: rec.unfiltered.options.length, note: rec.unfiltered.note } : null, filtered: rec.filtered ? { options: rec.filtered.options, groups: rec.filtered.groups, empty: rec.filtered.empty } : null };\n};\n",
 "steps/pos-menu.mjs": "// The till's own menu at Central Floresta, read through the platform's admin api on the till's origin (GET\n// /api/branches/:id/menu?includeBeoOnly=true), against what the BEO's picker is given (the app's door). Read only.\nexport default async (S) => {\n  if (!S.ctxs.pos) {\n    const api = await S.request.newContext({ baseURL: S.POS });\n    const r = await api.post('/api/auth/sign-in', { data: { phone: S.need('STAGING_ADMIN_PHONE'), password: S.need('STAGING_ADMIN_PASSWORD') } });\n    S.assert.equal(r.status(), 200, 'POS admin sign-in ' + r.status());\n    S.ctxs.pos = { api };\n  }\n  const { api } = S.ctxs.pos;\n  const branches = await S.call(api, S.POS, 'GET', '/branches');\n  const b = (branches.body?.branches ?? []).find((x) => x.id === S.st.app.coreBranchId);\n  S.assert.ok(b, 'the platform branch the app links Central Floresta to');\n  const menuAll = await S.call(api, S.POS, 'GET', `/branches/${b.id}/menu?includeBeoOnly=true`);\n  const menuTill = await S.call(api, S.POS, 'GET', `/branches/${b.id}/menu`);\n  S.assert.equal(menuAll.status, 200);\n  const products = menuAll.body.products;\n  const cats = new Map(menuAll.body.categories.map((c) => [c.id, c]));\n  const scoped = products.filter((p) => !p.branchId || p.branchId === b.id);\n  const isFood = (p) => p.kind === 'menu' && (p.effectivePrepStation === 'kitchen' || p.effectivePrepStation === 'bar');\n  const live = (p) => p.active && !p.archivedAt;\n  const expected = scoped.filter((p) => isFood(p) && live(p) && p.code && p.code.trim());\n  const door = S.st.tillMenuItems;\n  const doorCodes = new Set(door.map((i) => i.code));\n  const expCodes = new Set(expected.map((p) => p.code.trim()));\n  const missing = expected.filter((p) => !doorCodes.has(p.code.trim())).map((p) => ({ code: p.code, name: p.name }));\n  const extra = door.filter((i) => !expCodes.has(i.code)).map((i) => ({ code: i.code, name: i.name }));\n  const mismatched = [];\n  for (const i of door) {\n    const p = expected.find((x) => x.code.trim() === i.code);\n    if (!p) continue;\n    const diffs = [];\n    if (p.name !== i.name) diffs.push(`name till \"${p.name}\" door \"${i.name}\"`);\n    if (p.priceSatang !== i.priceSatang) diffs.push(`price till ${p.priceSatang} door ${i.priceSatang}`);\n    if ((p.effectiveWeekendSatang ?? p.priceSatang) !== i.priceWeekendSatang) diffs.push(`weekend till ${p.effectiveWeekendSatang} door ${i.priceWeekendSatang}`);\n    if (p.effectivePrepStation !== i.station) diffs.push(`station till ${p.effectivePrepStation} door ${i.station}`);\n    if (!!p.beoOnly !== i.beoOnly) diffs.push('beoOnly');\n    const own = p.categoryId ? cats.get(p.categoryId) : null;\n    if ((own?.name ?? null) !== i.category) diffs.push(`category till ${own?.name} door ${i.category}`);\n    if (diffs.length) mismatched.push({ code: i.code, diffs });\n  }\n  // What the till sells at the kitchen or the bar that the picker can never offer, and why.\n  const sellable = scoped.filter((p) => p.kind === 'menu' && live(p) && !p.beoOnly);\n  const uncodedFood = sellable.filter((p) => isFood(p) && !(p.code && p.code.trim())).map((p) => ({ name: p.name, station: p.effectivePrepStation, category: cats.get(p.categoryId)?.name ?? null }));\n  const noStation = sellable.filter((p) => !isFood(p)).map((p) => ({ name: p.name, code: p.code, station: p.effectivePrepStation }));\n  const offSale = scoped.filter((p) => p.kind === 'menu' && !p.active && !p.archivedAt && p.code).map((p) => ({ code: p.code, name: p.name }));\n  const codes = expected.map((p) => p.code.trim());\n  const dupCodes = codes.filter((c, i) => codes.indexOf(c) !== i);\n  const tillSells = (menuTill.body?.products ?? []).filter((p) => (!p.branchId || p.branchId === b.id) && p.kind === 'menu' && live(p));\n  const sample = ['Margherita', 'Pizza', 'Juice', 'Coke', 'Calamari', 'Hummus', 'French'].map((w) => ({ word: w, till: expected.filter((p) => p.name.toLowerCase().includes(w.toLowerCase())).map((p) => `${p.code} ${p.name}`), door: door.filter((i) => i.name.toLowerCase().includes(w.toLowerCase())).map((i) => `${i.code} ${i.name}`) }));\n  S.st.posMenu = {\n    platformBranch: { id: b.id, name: b.name, partySlipsStationId: b.partySlipsStationId ?? null },\n    routes: { withBeoOnly: `GET /api/branches/:id/menu?includeBeoOnly=true ${menuAll.status}`, tillSelling: `GET /api/branches/:id/menu ${menuTill.status}` },\n    products: { total: products.length, atThisBranchOrOperatorWide: scoped.length },\n    expected: expected.length, door: door.length,\n    doorByStation: { kitchen: door.filter((i) => i.station === 'kitchen').length, bar: door.filter((i) => i.station === 'bar').length, beoOnly: door.filter((i) => i.beoOnly).length },\n    missingFromDoor: missing, extraInDoor: extra, mismatched, duplicateCodes: dupCodes,\n    sameOrder: JSON.stringify(door.map((i) => i.code)) === JSON.stringify(door.map((i) => i.code)),\n    tillSellingGridMenuItems: tillSells.length,\n    uncodedKitchenBarItemsOnSale: uncodedFood,\n    menuItemsPrintingNowhereOnSale: noStation,\n    offSaleCodedItems: offSale,\n    sample,\n  };\n  S.save();\n  return { ...S.st.posMenu, uncodedKitchenBarItemsOnSale: uncodedFood.length, uncodedSample: uncodedFood.slice(0, 15), menuItemsPrintingNowhereOnSale: noStation.length, noStationSample: noStation.slice(0, 10) };\n};\n",
 "steps/save.mjs": "// Save BEO (the sheet's Save), the writes it sends and their answers, the toasts; then the BEO read back through\n// the app's own route (GET /api/events/:id/beo): the kitchen and bar lines as saved. arg = \"<key>\"\nexport default async (S, arg) => {\n  const key = arg || 'save';\n  const page = S.ctxs.app.page;\n  const writes = [];\n  const on = (r) => {\n    try {\n      const u = new URL(r.url());\n      const m = r.request().method();\n      if (m !== 'GET' && u.pathname.startsWith('/api/')) writes.push({ method: m, path: u.pathname.replace(/[0-9a-f]{8}-[0-9a-f-]{27}/g, ':id'), status: r.status() });\n    } catch {}\n  };\n  page.on('response', on);\n  const t0 = Date.now();\n  const done = page.waitForResponse((r) => /\\/api\\/events\\/[^/]+\\/beo$/.test(new URL(r.url()).pathname) && r.request().method() === 'PUT', { timeout: 120000 });\n  await page.getByTestId('button-save-beo').click();\n  const resp = await done;\n  await page.waitForTimeout(2500);\n  page.off('response', on);\n  const toasts = (await page.locator('li[role=status]').allInnerTexts().catch(() => [])).map((t) => S.scrub(S.one(t)));\n  const read = await readBeo(S);\n  const rec = { at: new Date().toISOString(), putStatus: resp.status(), ms: Date.now() - t0, writes, toasts, read };\n  (S.st.saves ??= {})[key] = rec;\n  S.save();\n  return rec;\n};\n\nexport async function readBeo(S) {\n  const r = await S.call(S.ctxs.app.ctx, S.APP, 'GET', `/events/${S.st.event.id}/beo`);\n  const kp = r.body?.kitchenPlan ?? null;\n  const bp = r.body?.barPlan ?? null;\n  const line = (l) => ({ itemName: l.itemName, productCode: l.productCode ?? null, quantity: l.quantity, price: l.price ?? null, included: l.included ?? null, source: l.source ?? null, groupId: l.groupId ?? null, notes: l.notes || null });\n  return {\n    route: 'GET /api/events/:id/beo', status: r.status,\n    kitchen: kp ? { setMenuEnabled: kp.setMenuEnabled ?? null, setMenuTemplateId: kp.setMenuTemplateId ?? null, adultsDiffer: kp.menus?.adultsDiffer ?? null, kids: (kp.menus?.kids ?? []).map(line), adults: (kp.menus?.adults ?? []).map(line) } : null,\n    bar: bp ? { items: (bp.items ?? []).map(line) } : null,\n  };\n}\n",
 "steps/searches.mjs": "// SCRUM-939: one picker opened, its unfiltered list read, then each search typed in turn and what it lists read in\n// the order shown (a picture of the sheet per pictured word); optionally a pick from the last word's list.\n// arg = JSON { tid, key, pictures: { \"<word>\": \"<file.png>\", \"\": \"<file for the unfiltered list>\" }, words: [..],\n//              pick: \"<code>\" | null }\nimport { hideBoard, showBoard } from './applib.mjs';\nimport { listed } from './pick.mjs';\nexport default async (S, arg) => {\n  const a = JSON.parse(arg);\n  const { tid, key = tid, pictures = {}, words = [], pick = null } = a;\n  const page = S.ctxs.app.page;\n  const sheet = page.locator('[role=dialog]').first();\n  const btn = page.getByTestId(tid);\n  await btn.evaluate((el) => el.scrollIntoView({ block: 'center' }));\n  await page.waitForTimeout(300);\n  await btn.click();\n  await page.locator('[data-radix-popper-content-wrapper]').waitFor({ timeout: 30000 });\n  await page.getByTestId(`${tid}-search`).waitFor({ timeout: 60000 });\n  await page.waitForTimeout(500);\n  const rec = { at: new Date().toISOString(), tid, title: await btn.getAttribute('title'), searchBoxAtOpen: await page.getByTestId(`${tid}-search`).inputValue() };\n  const un = await listed(page, tid);\n  rec.unfiltered = { count: un.options.length, groups: un.groups, first: un.options.slice(0, 8).map((o) => o.text), clear: un.clear };\n  const snap = async (file, shows) => {\n    // The list keeps its scroll between searches; a picture shows it from its top.\n    await page.evaluate(() => { const l = document.querySelector('[data-radix-popper-content-wrapper] [cmdk-list]'); if (l) l.scrollTop = 0; });\n    await hideBoard(page);\n    try { return await S.shot(page, file, { element: sheet, shows }); } finally { await showBoard(page); }\n  };\n  if (pictures['']) rec.unfiltered.picture = await snap(pictures[''], `${tid}: the picker open, nothing typed`);\n  rec.searches = [];\n  for (const w of words) {\n    await page.getByTestId(`${tid}-search`).fill('');\n    await page.waitForTimeout(250);\n    await page.getByTestId(`${tid}-search`).fill(w);\n    await page.waitForTimeout(700);\n    const l = await listed(page, tid);\n    const s = { typed: w, count: l.options.length, listed: l.options.map((o) => o.text), codes: l.options.map((o) => o.code), groups: l.groups, empty: l.options.length ? null : l.empty, clearShown: l.clear };\n    if (pictures[w]) s.picture = await snap(pictures[w], `${tid}: \"${w}\" typed in the picker`);\n    rec.searches.push(s);\n  }\n  if (pick) {\n    const opt = page.getByTestId(`${tid}-option-${pick}`);\n    rec.pickedText = S.one(await opt.innerText());\n    await opt.click();\n    await page.waitForTimeout(500);\n    rec.closedAfterPick = !(await page.locator('[data-radix-popper-content-wrapper]').isVisible().catch(() => false));\n    rec.picked = pick;\n  } else {\n    await page.keyboard.press('Escape');\n    await page.waitForTimeout(300);\n  }\n  ((S.st.searches ??= {})[key] ??= []).push(rec);\n  S.save();\n  return rec;\n};\n",
 "steps/settings939.mjs": "// Settings > Set menu templates, a NEW template's dialog (never saved, nothing typed but the search, closed with\n// Cancel): the Always Included item's Code box search, nothing typed and \"fries\". Templates read before and after\n// through GET /api/beo/set-menu-templates; nothing created, edited or deleted.\nimport { listed } from './pick.mjs';\nexport default async (S, arg) => {\n  const page = S.ctxs.app.page;\n  const { ctx } = S.ctxs.app;\n  const templates = async () => {\n    const r = await S.call(ctx, S.APP, 'GET', '/beo/set-menu-templates');\n    return (Array.isArray(r.body) ? r.body : []).map((t) => ({ id: t.id, name: t.name, isActive: t.isActive, updatedAt: t.updatedAt ?? null, items: JSON.stringify(t.items) }));\n  };\n  const rec = (S.st.settings ??= {});\n  const avatar = [page.locator('span.rounded-full.bg-primary')];\n  const dlg = page.getByRole('dialog', { name: /Set Menu Template/ });\n  await page.goto(S.APP + '/studio/event-settings', { waitUntil: 'domcontentloaded', timeout: 120000 });\n  await page.getByTestId('tab-set-menus').waitFor({ timeout: 120000 });\n  await page.getByTestId('tab-set-menus').click();\n  await page.getByTestId('button-add-set-menu-template').waitFor({ timeout: 60000 });\n  await page.waitForTimeout(1500);\n  rec.before = await templates();\n  await page.getByTestId('button-add-set-menu-template').click();\n  await dlg.waitFor({ timeout: 30000 });\n  rec.dialogTitle = S.one(await dlg.locator('h2').first().innerText());\n  await page.getByTestId('button-add-always-included').click();\n  await page.waitForTimeout(400);\n  const codeBox = dlg.locator('[data-testid^=\"input-set-menu-item-code-\"]').first();\n  const itemId = (await codeBox.getAttribute('data-testid')).slice('input-set-menu-item-code-'.length);\n  const btn = `button-set-menu-item-till-${itemId}`;\n  await page.getByTestId(btn).click();\n  await page.getByTestId(`${btn}-search`).waitFor({ timeout: 30000 });\n  await page.waitForTimeout(500);\n  const un = await listed(page, btn);\n  rec.unfiltered = { count: un.options.length, groups: un.groups };\n  await page.getByTestId(`${btn}-search`).fill('fries');\n  await page.waitForTimeout(700);\n  const l = await listed(page, btn);\n  rec.fries = { count: l.options.length, listed: l.options.map((o) => o.text), codes: l.options.map((o) => o.code), groups: l.groups };\n  rec.picture = await S.shot(page, arg || '07-p5-settings-new-template-code-search-fries.png', { mask: avatar, shows: 'Settings > Set menu templates > Add (a new template, never saved): the Code box\\'s search, \"fries\" typed' });\n  await page.keyboard.press('Escape');\n  await page.waitForTimeout(400);\n  if (await dlg.isVisible().catch(() => false)) {\n    await dlg.getByRole('button', { name: 'Cancel', exact: true }).click();\n    await page.waitForTimeout(800);\n    rec.closedWith = 'Cancel';\n  } else rec.closedWith = 'Escape (the popover and the dialog closed together)';\n  rec.dialogClosed = !(await dlg.isVisible().catch(() => false));\n  rec.after = await templates();\n  rec.unchanged = JSON.stringify(rec.after) === JSON.stringify(rec.before) && JSON.stringify(rec.after) === JSON.stringify(S.st.templatesAtStart);\n  S.save();\n  return { dialogTitle: rec.dialogTitle, unfiltered: rec.unfiltered, fries: rec.fries, closedWith: rec.closedWith, dialogClosed: rec.dialogClosed, before: rec.before.length, after: rec.after.length, unchanged: rec.unchanged };\n};\n",
 "steps/signout.mjs": "// Every session of this run signed out, each read back: the administrator's OTO App and launcher sessions, and the\n// platform admin api session on the till's origin. (The manager and reception sessions were signed out in role.mjs.)\nexport default async (S) => {\n  const safe = (p) => p.catch((e) => ({ status: 'error ' + e.message }));\n  const out = { at: new Date().toISOString() };\n  if (S.ctxs.app) {\n    const { ctx } = S.ctxs.app;\n    out.app = {\n      appLogout: (await safe(S.call(ctx, S.APP, 'POST', '/logout', {}))).status,\n      launcherSignOut: (await safe(S.call(ctx, S.LAUNCHER, 'POST', '/auth/sign-out', {}))).status,\n      appUserAfter: (await safe(S.call(ctx, S.APP, 'GET', '/user'))).status,\n      launcherMeAfter: (await safe(S.call(ctx, S.LAUNCHER, 'GET', '/me'))).status,\n    };\n    await ctx.close().catch(() => {});\n  }\n  if (S.ctxs.pos) {\n    const { api } = S.ctxs.pos;\n    out.pos = {\n      signOut: (await safe(S.call(api, S.POS, 'POST', '/auth/sign-out', {}))).status,\n      meAfter: (await safe(S.call(api, S.POS, 'GET', '/me'))).status,\n    };\n    await api.dispose().catch(() => {});\n  }\n  S.st.signOut = out;\n  S.save();\n  return out;\n};\n"
};
const dir = process.argv[2];
if (!dir) { console.log(Object.keys(FILES).join('\n')); process.exit(0); }
for (const [name, text] of Object.entries(FILES)) { const f = resolve(dir, name); mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, text); }
console.log('written', Object.keys(FILES).length, 'files to', dir);
